def has_close_duplicate(nums, k):
    if k < 0:
        return False
    window = set()
    for i, n in enumerate(nums):
        if i - k - 1 >= 0:
            window.discard(nums[i - k - 1])
        if n in window:
            return True
        window.add(n)
    return False
